const body = ($input.first().json.body) || {};
const meetingId = body.meeting_id || body.meetingId || '';
const crid = body.client_reference_id || body.clientReferenceId || '';
const eventType = body.event || body.eventType || '';
// Гейт: Drive-транскрипты обрабатывает отдельный воркфлоу — сюда их не пускаем
if (crid.indexOf('drive:') === 0) { return []; }
const ffBody = { query: 'query Transcript($transcriptId: String!) { transcript(id: $transcriptId) { title date duration sentences { speaker_name text } } }', variables: { transcriptId: meetingId } };
return [{ json: { meetingId: meetingId, clientReferenceId: crid, eventType: eventType, ffBody: ffBody } }];

const crid = ($('Prep FF Query').item.json.clientReferenceId) || '';
let zoomUrl = '';
if (crid) { let enc = encodeURIComponent(crid); if (crid.indexOf('/') !== -1 || crid.indexOf('+') !== -1) { enc = encodeURIComponent(enc); } zoomUrl = 'https://api.zoom.us/v2/past_meetings/' + enc + '/participants?page_size=100'; }
return [{ json: { crid: crid, zoomUrl: zoomUrl, hasUuid: !!crid } }];

const ft = $('Fetch Transcript').item.json;
if (ft && ft.errors && ft.errors.length) { throw new Error('Fireflies error: ' + (ft.errors[0].message || 'unknown') + ' (transcriptId=' + (($('Prep FF Query').item.json.meetingId) || '') + ')'); }
const data = (ft.data && ft.data.transcript) ? ft.data.transcript : (ft.transcript || {});
const sentences = data.sentences || [];
if (!sentences.length) { throw new Error('Пустой транскрипт от Fireflies (transcriptId=' + (($('Prep FF Query').item.json.meetingId) || '') + '). Проверь meeting_id/client_reference_id во входящем вебхуке.'); }
let transcriptText = '';
for (let i = 0; i < sentences.length; i++) { const s = sentences[i] || {}; transcriptText += (s.speaker_name || 'Спикер') + ': ' + (s.text || '') + '\n'; }
const title = data.title || '';
const date = data.date || '';
const duration = (data.duration != null) ? data.duration : '';
const zoomResp = $input.first().json;
let names = [];
try { const ps = (zoomResp && zoomResp.participants) ? zoomResp.participants : []; for (let i = 0; i < ps.length; i++) { const p = ps[i]; if (p && p.name && names.indexOf(p.name) === -1) names.push(String(p.name).trim()); } } catch (e) {}
const namesHint = names.length ? ('\n\nПодсказка — участники встречи по данным Zoom: ' + names.join(', ') + '. Используй эти имена, чтобы точнее определить менеджера(ов) и контакт(ы) клиента. Имена могут быть неполными или «Гость» — тогда опирайся на транскрипт и список менеджеров. Не выдумывай.') : '';
// === НАСТРОЙКА: впишите свой тип встречи, услуги и вопросы ===
const MEETING_TYPE = 'обзорная встреча с клиентом';
const MEETING_TYPE_DESC = 'регулярная встреча про удовлетворённость и развитие сотрудничества';
const OUR_SERVICES = 'перечислите свои услуги';
// key — ключ в ответе модели, column — колонка таблицы, text — формулировка и цель
const QUESTIONS = [
 { key: 'q1_satisfaction', column: 'Оценка и удовлетворённость', text: 'Оценка сотрудничества 1–10, чем доволен и что беспокоит. Цель: лояльность и риски оттока.' },
 { key: 'q2_business_changes', column: 'Что изменилось в бизнесе', text: 'Что изменилось в бизнесе клиента за последнее время, как на него влияет рынок. Цель: контекст и финансовое состояние.' },
 { key: 'q3_goals', column: 'Цели и приоритеты', text: 'Цели и приоритеты клиента на ближайшие месяцы. Цель: куда движется клиент.' },
 { key: 'q4_alternatives', column: 'Альтернативные решения / конкуренты', text: 'Какие альтернативы, других подрядчиков или инструменты использует. Цель: конкуренты.' },
 { key: 'q5_service_usage', column: 'Использование наших услуг', text: 'Какими нашими услугами пользуется и насколько полно. Цель: охват.' },
 { key: 'q6_blockers', column: 'Что мешает', text: 'Что мешает получать больше пользы от работы с нами. Цель: препятствия и точки улучшения.' },
 { key: 'q7_untapped', column: 'Задачи у других подрядчиков', text: 'Задачи и проекты, которые клиент решает сам или с другими подрядчиками, и почему. Цель: упущенное.' },
 { key: 'q8_wishes', column: 'Предложения и пожелания клиента', text: 'Что клиент сам озвучил или попросил: новые услуги/инструменты у нас; изменения в работе (сроки, формат, отчётность); любые явные пожелания и просьбы. Цель: прямые запросы и пожелания клиента.' },
 { key: 'q9_expansion_terms', column: 'Условия расширения', text: 'При каких условиях готов расширить сотрудничество. Цель: условия роста.' },
 { key: 'q10_referrals', column: 'Партнёры для рекомендации', text: 'Партнёры или знакомые, которым мог бы нас порекомендовать. Цель: рефералы.' }
];
// ==============================================================
const managers = [
 'Анна (Соколова Анна / Анна / Аня)',
 'Дмитрий (Орлов Дмитрий / Дмитрий / Дима)',
 'Елена (Белова Елена / Елена / Лена)',
 'Сергей (Новиков Сергей / Сергей / Серёжа)',
 'Наталья (Кравцова Наталья / Наталья / Наташа)'
];
const system = [
 'Ты — ассистент, который анализирует транскрипт деловой встречи на русском языке.',
 'Сначала определи, целевая ли это встреча: ' + MEETING_TYPE + ' (' + MEETING_TYPE_DESC + ') — или содержит её элементы. Этот же Zoom используется и для планёрок, онбординга и прочего — такие встречи нам не нужны.',
 'Если встреча целевая (полностью или частично) — извлеки ответы по ' + QUESTIONS.length + ' вопросам и доп. блоки.',
 '',
 'ВАЖНО про гибкость:',
 '- Ищи ответы по СМЫСЛУ по всему транскрипту, а не в ожидаемом месте.',
 '- Ответ может быть рассыпан по нескольким репликам — собери воедино.',
 '- Клиент может ответить, не дожидаясь прямого вопроса — это валидный ответ.',
 '- Если есть только косвенные признаки — извлеки суть, не выдумывай.',
 '- Различай реальный ответ и тему, упомянутую вскользь без содержания (тогда пусто).',
 '',
 'Менеджеры и руководители (наша сторона) и допустимые формы их имени: ' + managers.join('; ') + '.',
 'КАК ОПРЕДЕЛИТЬ manager и contact_name: НАШ менеджер — тот, кто ПРОВОДИТ встречу и ЗАДАЁТ вопросы (про бизнес собеседника, удовлетворённость, развитие сотрудничества). КЛИЕНТ — тот, ЧЕЙ бизнес обсуждают и кто ОТВЕЧАЕТ. Опирайся на подсказку об участниках выше и на роли в диалоге, а не только на совпадение имени.',
 'КОЛЛИЗИЯ ИМЁН: если КЛИЕНТА зовут так же, как кого-то из нашего списка (например, клиента тоже зовут Анна, Дмитрий, Сергей и т.п.) — он ВСЁ РАВНО КЛИЕНТ. Само совпадение имени НЕ делает участника нашим менеджером; засчитывай менеджером только того, кто реально ведёт встречу и задаёт вопросы.',
 'В поле manager выводи каноническое полное имя менеджера (первое слово до скобок), несколько через запятую если наших несколько. Остальные участники — contact_name (через запятую). Имена не выдумывай; если не названо — пусто.',
 '',
 'Вопросы (ключ — формулировка — цель):',
 ...QUESTIONS.map((q) => q.key + ' — ' + q.text),
 '',
 'Дополнительно:',
 '- agreements — договорённости/next steps;',
 '- company_summary — сводка о компании клиента из диалога: чем занимается, масштаб, направления, ситуация в бизнесе;',
 '- growth_opportunities — аналитический срез про самого клиента и его бизнес: куда движется, намерения и тренды, спящий потенциал, и зоны, где МЫ могли бы вырасти ВНЕ текущих услуг (наши основные услуги: ' + OUR_SERVICES + '). Это твой вывод из контекста, а не прямая просьба клиента. НЕ дублируй сюда то, что клиент явно попросил — это идёт в q8_wishes. Помечай: сказано прямо или это твоё предположение.',
 '',
 'Верни СТРОГО валидный JSON без markdown по схеме:',
 '{ "is_target_meeting": true, "target_signal": "full|partial|none", "reason": "", "contact_name": "", "manager": "", "answers": { ' + QUESTIONS.map((q) => '"' + q.key + '":""').join(', ') + ' }, "agreements":"", "company_summary":"", "growth_opportunities":"" }',
 'Если по вопросу нет ответа — пустая строка. Если встреча не целевая — is_target_meeting:false и target_signal:"none".'
].join('\n');
const user = 'Заголовок встречи: ' + title + '\nДата: ' + date + namesHint + '\n\nТранскрипт:\n' + transcriptText;
const openaiBody = { model: 'gpt-5.4', messages: [ { role: 'system', content: system }, { role: 'user', content: user } ], response_format: { type: 'json_object' } };
return [{ json: { meetingId: ($('Prep FF Query').item.json.meetingId) || '', date: date, duration: duration, openaiBody: openaiBody, questions: QUESTIONS.map((q) => ({ key: q.key, column: q.column })) } }];

const resp = $input.first().json;
// Сбой модели — это ошибка, а не «встреча не того типа»: бросаем исключение,
// чтобы сработал общий обработчик ошибок и встреча не пропала молча.
if (resp.error) { throw new Error('Модель вернула ошибку: ' + (resp.error.message || JSON.stringify(resp.error))); }
if (!resp.choices || !resp.choices[0] || !resp.choices[0].message) { throw new Error('В ответе модели нет choices: ' + JSON.stringify(resp).slice(0, 300)); }
let content = resp.choices[0].message.content || '';
content = content.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = null;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('Ответ модели не разбирается как JSON: ' + content.slice(0, 300)); }
if (!parsed || typeof parsed.is_target_meeting !== 'boolean') { throw new Error('В ответе модели нет поля is_target_meeting: ' + content.slice(0, 300)); }
if (!parsed || parsed.is_target_meeting !== true) { return []; }
const bp = $('Build Prompt').item.json;
const meetingId = bp.meetingId || '';
const dateMs = bp.date || 0;
const p = (n) => String(n).padStart(2, '0');
let dateStr = '';
if (dateMs) { try { const d = new Date(Number(dateMs) + 3*3600*1000); dateStr = d.getUTCFullYear() + '-' + p(d.getUTCMonth()+1) + '-' + p(d.getUTCDate()); } catch (e) { dateStr = ''; } }
let durMin = '';
if (bp.duration !== undefined && bp.duration !== null && bp.duration !== '') { const dv = Number(bp.duration); if (!isNaN(dv)) durMin = Math.round(dv); }
const MGR = [
 {full:'Анна',    keys:['анна','аня','соколова']},
 {full:'Дмитрий', keys:['дмитрий','дима','орлов']},
 {full:'Елена',   keys:['елена','лена','белова']},
 {full:'Сергей',  keys:['сергей','сережа','новиков']},
 {full:'Наталья', keys:['наталья','наташа','кравцова']}
];
const normMgr = (raw) => {
  if (!raw) return '';
  const out = [];
  String(raw).split(',').forEach((part) => {
    const words = part.toLowerCase().replace(/ё/g, 'е').split(/[^а-я]+/).filter(Boolean);
    let canon = '';
    for (const m of MGR) { if (m.keys.some((k) => words.includes(k))) { canon = m.full; break; } }
    const val = canon || part.trim();
    if (val && out.indexOf(val) === -1) out.push(val);
  });
  return out.join(', ');
};
const a = parsed.answers || {};
const row = {
  'Дата встречи': dateStr,
  'Клиент': '',
  'Имя контакта': parsed.contact_name || '',
  'Менеджер': normMgr(parsed.manager),
  'Длительность (мин)': durMin,
  ...Object.fromEntries((bp.questions || []).map((q) => [q.column, a[q.key] || ''])),
  'Договорённости / Next Steps': parsed.agreements || '',
  'О компании': parsed.company_summary || '',
  'Перспективы и зоны роста': parsed.growth_opportunities || '',
  'ID встречи (Fireflies)': meetingId
};
return [{ json: row }];

const manager = ($('Parse').item.json['Менеджер']) || '';
const dateMs = ($('Build Prompt').item.json.date) || 0;
const p = (n) => String(n).padStart(2, '0');
let datePart = ''; let timeStr = '';
if (dateMs) { try { const d = new Date(Number(dateMs) + 3*3600*1000); datePart = p(d.getUTCDate()) + '-' + p(d.getUTCMonth()+1) + '-' + d.getUTCFullYear(); timeStr = p(d.getUTCHours()) + '-' + p(d.getUTCMinutes()); } catch (e) {} }
const base = manager ? manager : 'Без менеджера';
const folderName = base + ' - ' + (datePart || 'без даты') + (timeStr ? (' ' + timeStr) : '');
return [{ json: { folderName: folderName } }];

const row = Object.assign({}, $('Parse').item.json);
const created = $input.first().json || {};
const fid = created.id || '';
row['Папка встречи'] = fid ? ('https://drive.google.com/drive/folders/' + fid) : '';
return [{ json: row }];

const ft = $('Fetch Transcript').item.json;
const data = (ft.data && ft.data.transcript) ? ft.data.transcript : (ft.transcript || {});
const sentences = data.sentences || [];
const title = data.title || 'Транскрипт';
let text = title + '\n\n';
for (let i = 0; i < sentences.length; i++) { const s = sentences[i] || {}; text += (s.speaker_name || 'Спикер') + ': ' + (s.text || '') + '\n'; }
const folderId = ($('Create Meeting Folder').item.json.id) || '';
return [{ json: { transcriptText: text, transcriptName: 'Транскрипт (Fireflies).txt', folderId: folderId } }];

const crid = ($('Prep Zoom').item.json.crid) || '';
let recUrl = '';
if (crid) { let enc = encodeURIComponent(crid); if (crid.indexOf('/') !== -1 || crid.indexOf('+') !== -1) { enc = encodeURIComponent(enc); } recUrl = 'https://api.zoom.us/v2/meetings/' + enc + '/recordings'; }
const folderId = ($('Create Meeting Folder').item.json.id) || '';
return [{ json: { recUrl: recUrl, folderId: folderId } }];

const resp = $input.first().json || {};
const files = resp.recording_files || [];
const folderId = ($('Create Meeting Folder').item.json.id) || '';
let bestMp4 = null, bestM4a = null;
for (let i = 0; i < files.length; i++) {
  const f = files[i]; if (!f || !f.file_type) continue;
  const t = String(f.file_type).toUpperCase(); const sz = Number(f.file_size || 0);
  if (t === 'MP4') { if (!bestMp4 || sz > Number(bestMp4.file_size || 0)) bestMp4 = f; }
  else if (t === 'M4A') { if (!bestM4a || sz > Number(bestM4a.file_size || 0)) bestM4a = f; }
}
const out = [];
if (bestMp4 && bestMp4.download_url) out.push({ json: { download_url: bestMp4.download_url, fileName: 'Видеозапись.mp4', folderId: folderId } });
if (bestM4a && bestM4a.download_url) out.push({ json: { download_url: bestM4a.download_url, fileName: 'Аудио.m4a', folderId: folderId } });
return out;
